class RealTimeMeasurementsPage(NavigatablePage):
    """
    As a class will be called by Performance,
    all operations on RealTime Measurements will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Performance', 'Performance Management', 'Real-time Measurements']

    def __init__(self, driver, download_checker):
        super(RealTimeMeasurementsPage, self).__init__(driver)
        self._navigation_panel = RealTimeMeasurementsPageNavigationPanel(driver)
        self._view_panel = RealTimeMeasurementsPageViewPanel(driver, download_checker)

    def download_real_time_measurements_counters(self, object_names, timeout):
        """
        Downloading real time measurements counters
        """
        self._navigation_panel.filter_counter(object_names)
        return self._view_panel.download_real_time_measurements_counters(timeout)

    def get_real_time_measurements(self, object_names, measured_object=None, timeout=60):
        self._navigation_panel.filter_counter(object_names, timeout)
        measurements = self._view_panel.get_real_time_measurements(measured_object, timeout)
        self._navigation_panel.filter_counter(object_names, timeout)
        return measurements

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class RealTimeMeasurementsPageNavigationPanel(NavigationPanel):
    _EXPAND_ICON_XPATH = '//div[@class="tree-list-row-container"]//*[contains(@class, "icon") and @role="button"]'
    _AVAILABLE_OBJECT_FILTER_XPATH = ("//ui-text-input[contains(@a-placeholder, 'Available Object') or "
                                      "contains(@a-placeholder, 'Object name')]//input")
    _OBJECT_NAME = '//highlighter[@text="{}"]'
    _OBJECT_NAME_CHECKBOX = _OBJECT_NAME + '/preceding::label[1]//span'

    def __init__(self, driver):
        super(RealTimeMeasurementsPageNavigationPanel, self).__init__(driver)

    def filter_counter(self, object_names, timeout):
        if isinstance(object_names, six.string_types):
            object_names = [object_names]
        for name in object_names:
            self._filter_object_name(name, timeout)
            self._select_object(name, timeout)

    def _filter_object_name(self, object_name, timeout):
        self.wait_for_visibility_by_xpath(self._EXPAND_ICON_XPATH, timeout)
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._AVAILABLE_OBJECT_FILTER_XPATH), object_name)
        self.wait_for_text_present_in_attribute(self._AVAILABLE_OBJECT_FILTER_XPATH, "class", "ng-not-empty")

    def _select_object(self, object_name, timeout):
        self.wait_for_visibility_by_xpath(self._OBJECT_NAME.format(object_name), timeout)
        self.click_enabled_element((By.XPATH, self._OBJECT_NAME_CHECKBOX.format(object_name)))


class RealTimeMeasurementsPageViewPanel(ViewPanel):
    _MEASURED_INPUT_XPATH = '//im-counters-main//ui-text-input//input'
    _MEASURED_OBJECT_XPATH = '//div[@class="im-counters-table-container"]//thead//th[@colspan="2"]'
    _IM_COUNTER_TBODY_TR_XPATH = '//div[@class="im-counters-table-container"]//tbody//tr'
    _MEASURED_TYPE = ['Voltage', 'Power']

    def __init__(self, driver, download_checker):
        super(RealTimeMeasurementsPageViewPanel, self).__init__(driver)
        self.common_actions = {
            'download_real_time_measurements_counters':
                PerformanceCommonAction(driver, download_checker).export_counters_info_to_csv,
        }
        self.__dict__.update(self.common_actions)

    def _get_real_time_measurements(self, timeout):
        table_data = {}
        measured_objects = []
        self.wait_for_visibility_by_xpath(self._MEASURED_OBJECT_XPATH, timeout)
        for measured_object in self.driver.find_elements_by_xpath(self._MEASURED_OBJECT_XPATH):
            measured_objects.append(measured_object.text)

        for index, tr_elem in enumerate(self.driver.find_elements_by_xpath(self._IM_COUNTER_TBODY_TR_XPATH)):
            time_data = tr_elem.find_element_by_xpath('td[contains(@class, "first-column")]').text
            data = [td.text for td in tr_elem.find_elements_by_xpath('td[contains(@class, "data-column")]')]

            for num in range(len(measured_objects)):
                tr_data = {time_data: dict(zip(self._MEASURED_TYPE, data[num * 2: (num + 1) * 2]))}
                measured_object = measured_objects[num]
                if measured_object not in table_data:
                    table_data.update({measured_object: tr_data})
                else:
                    table_data.get(measured_object).update(tr_data)

        return table_data

    def get_real_time_measurements(self, measured_object, timeout):
        if measured_object:
            self.insert_text_to_enable_element_and_enter((By.XPATH, self._MEASURED_INPUT_XPATH),
                                                         measured_object,
                                                         timeout)
        return self._get_real_time_measurements(timeout)
